+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.core.ui.ApplicationErrorView;
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import org.springframework.dao.DataAccessException;
+
+import java.util.stream.Stream;
+
+/** UC-002: View Veterinarians, with rows fetched as the visitor scrolls. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetsView extends VerticalLayout {
+
+    private final transient VetRepository repository;
+
+    public VetsView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+
+        Grid<Vet> grid = new Grid<>();
+        grid.addColumn(Vet::firstName).setHeader("First Name").setKey("firstName");
+        grid.addColumn(Vet::lastName).setHeader("Last Name").setKey("lastName");
+        grid.addColumn(vet -> vet.specialties().isEmpty()
+                ? "none" : String.join(", ", vet.specialties()))
+                .setHeader("Specialties").setKey("specialties");
+        grid.setSizeFull();
+        grid.setItems(query -> {
+            try {
+                return this.repository.findPage(query.getOffset(), query.getLimit());
+            } catch (DataAccessException exception) {
+                ApplicationErrorView.showException(exception);
+                return Stream.empty();
+            }
+        }, query -> {
+            try {
+                return this.repository.count();
+            } catch (DataAccessException exception) {
+                ApplicationErrorView.showException(exception);
+                return 0;
+            }
+        });
+        add(new H2("Veterinarians"), grid);
+        expand(grid);
+    }
+}
