+        var provider = grid.getDataProvider();
+        List<Vet> first = provider.fetch(new Query<>(0, 25, List.of(), null, null)).toList();
+        List<Vet> second = provider.fetch(new Query<>(25, 25, List.of(), null, null)).toList();
+        List<Vet> last = provider.fetch(new Query<>(125, 25, List.of(), null, null)).toList();
